    findFolder: F<
      {
        id?: string | null | undefined;
        path?: string | null | undefined;
      },
      R<"Folder">
    >;
    /** Queries for Files */
    findFolders: F<
      {
        folder_filter?: FolderFilterType | null | undefined;
        filter?: FindFilterType | null | undefined;
        ids?: Array<string> | null | undefined;
      },
      R<"FindFoldersResultType">
    >;
